code="from flask import Flask\nimport os, threading, time, requests, pytz\nfrom datetime import datetime\nfrom alpaca.trading.client import TradingClient\nfrom alpaca.trading.requests import MarketOrderRequest\nfrom alpaca.trading.enums import OrderSide, TimeInForce\nfrom alpaca.data.historical import StockHistoricalDataClient\nfrom alpaca.data.requests import StockLatestQuoteRequest\napp=Flask(__name__)\nTOKEN=os.environ.get('TELEGRAM_BOT_TOKEN','').strip()\nCHAT=os.environ.get('TELEGRAM_CHAT_ID','').strip()\nALPACA_KEY=os.environ.get('ALPACA_API_KEY','').strip()\nALPACA_SECRET=os.environ.get('ALPACA_SECRET_KEY','').strip()\nIS_PAPER=True\nSYMBOLS=['AAPL','MSFT','TSLA','NVDA','SPY']\nQTY=1\ntrading_client=TradingClient(ALPACA_KEY, ALPACA_SECRET, paper=IS_PAPER) if ALPACA_KEY else None\ndata_client=StockHistoricalDataClient(ALPACA_KEY, ALPACA_SECRET) if ALPACA_KEY else None\ndef send(msg):\n    print(msg)\n    try:\n        if TOKEN and CHAT:\n            requests.post(f'https://api.telegram.org/bot{TOKEN}/sendMessage', json={'chat_id': CHAT, 'text': msg}, timeout=10)\n    except Exception as e:\n        print(f'TG err {e}')\ndef get_price(sym):\n    try:\n        q=data_client.get_stock_latest_quote(StockLatestQuoteRequest(symbol_or_symbols=sym))\n        return (q[sym].bid_price + q[sym].ask_price)/2 if sym in q else None\n    except:\n        return None\ndef trading_loop():\n    send('🚀 Ross FREE Bot Started - LIVE Trading\\nPaper: '+str(IS_PAPER)+'\\nSymbols: '+','.join(SYMBOLS))\n    tz=pytz.timezone('US/Eastern')\n    traded_today=set()\n    while True:\n        try:\n            now=datetime.now(tz)\n            if now.weekday()>=5:\n                time.sleep(300)\n                continue\n            if now.hour==9 and now.minute==30 and now.second<30:\n                traded_today=set()\n                send(f'🔔 Market Open {now.strftime(\"%m/%d %H:%M\")} EST')\n            if 9<=now.hour<=15 and (now.hour!=9 or now.minute>=30):\n                for sym in SYMBOLS:\n                    if sym in traded_today:\n                        continue\n                    price=get_price(sym)\n                    if price:\n                        print(f'{sym} ${price:.2f}')\n                        if trading_client:\n                            try:\n                                trading_client.submit_order_for_account(MarketOrderRequest(symbol=sym, qty=QTY, side=OrderSide.BUY, time_in_force=TimeInForce.DAY))\n                                send(f'✅ BUY {sym} @ ${price:.2f}')\n                                traded_today.add(sym)\n                            except Exception as e:\n                                print(f'Order err {e}')\n                time.sleep(30)\n            else:\n                time.sleep(60)\n        except Exception as e:\n            print(f'Loop err {e}')\n            time.sleep(30)\napp.add_url_rule('/', 'home', lambda: 'Ross Bot FREE - FULL TRADING BOT LIVE - Telegram OK')\napp.add_url_rule('/health', 'health', lambda: 'OK')\nif __name__=='__main__':\n    threading.Thread(target=trading_loop, daemon=True).start()\n    app.run(host='0.0.0.0', port=int(os.environ.get('PORT', 10000)))\n"
exec(code)
